import sys
import time
from functools import wraps

def time_it(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        return result, end - start
    return wrapper

@time_it
def do_task(task):
    time.sleep(task[1])

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.rsplit(', ', 1)
    if len(parts) != 2:
        return
    task_name = parts[0].strip()
    try:
        duration = int(parts[1].strip())
    except ValueError:
        return
    task = (task_name, duration)
    result, elapsed = do_task(task)
    print(f"{task[0]} took {round(elapsed, 2)} seconds")

if __name__ == "__main__":
    main()
